import { createFeatureSelector, createSelector } from '@ngrx/store';
import * as fromChat from './chat.reducer';
export const selectChatState = createFeatureSelector('chat');
// Conversations selectors
export const selectConversationsState = createSelector(selectChatState, state => state.conversations);
export const {
  selectAll: selectAllConversations,
  selectEntities: selectConversationEntities,
  selectIds: selectConversationIds
} = fromChat.conversationsAdapter.getSelectors(selectConversationsState);
// Messages selectors
export const selectMessages = createSelector(selectChatState, state => state.messages);
export const {
  selectAll: selectAllMessages,
  selectEntities: selectMessageEntities,
  selectIds: selectMessageIds
} = fromChat.messagesAdapter.getSelectors(selectMessages);
// Other selectors
export const selectCurrentConversationId = createSelector(selectChatState, state => state.currentConversationId);
export const selectCurrentConversation = createSelector(selectConversationEntities, selectCurrentConversationId, (entities, id) => id ? entities[id] : null);
export const selectSearchResults = createSelector(selectChatState, state => state.searchResults);
export const selectMessageHistory = createSelector(selectChatState, state => state.messageHistory);
export const selectLoading = createSelector(selectChatState, state => state.loading);
export const selectSearching = createSelector(selectChatState, state => state.searching);
export const selectLoadingHistory = createSelector(selectChatState, state => state.loadingHistory);
export const selectError = createSelector(selectChatState, state => state.error);
export const selectSelectedMessage = createSelector(selectChatState, state => state.selectedMessage);
export const selectSelectedThread = createSelector(selectChatState, state => state.selectedThread);
export const selectThreadMessages = createSelector(selectChatState, state => state.threadMessages);
export const selectTypingUsers = createSelector(selectChatState, state => state.typingUsers);
export const selectHasMoreMessages = createSelector(selectChatState, state => state.hasMore);
